public class Ternario {
    static int max(int a, int b) {
        return a > b ? a : b;
    }

    public static void main(String[] args) {
        int n = 3;
        String msg = n == 1 ? "elemento" : "elementi";
        System.out.println(n + " " + msg);
        System.out.println(max(4, 9));
    }
}

