}

public class Somma {
    static int somma(int n) {
        int s = 0;
        for (int i = 1; i <= n; i++) {
            s += i;
        }
        return s;
    }

    public static void main(String[] args) {
        System.out.println(somma(10));
    }
}

public class Ripeti {
    public static void main(String[] args) {
        int n = 3;
        while (n > 0) {
            System.out.println("Conto alla rovescia: " + n);
            n--;
        }
        int k = 10;
        do {
            System.out.println("Eseguito una volta, k = " + k);
            k++;
        } while (k < 5);
    }
}

