public class Pattern {
    static String descrivi(Object o) {
        if (o instanceof String s && s.length() > 3) {
            return "Testo lungo: " + s.toUpperCase();
        }
        if (o instanceof Integer n) {
            return "Intero: " + (n + 1);
        }
        return "Altro";
    }
}

public class Fattoriale {
    static long fat(int n) {
        if (n <= 1) {
            return 1;
        }
        return n * fat(n - 1);
    }

    public static void main(String[] args) {
        System.out.println(fat(5));
    }
}

