public class Somme {
    static int somma(int a, int b) { return a + b; }
    static double somma(double a, double b) { return a + b; }
    static int somma(int a, int b, int c) { return a + b + c; }

    public static void main(String[] args) {
        System.out.println(somma(1, 2));
        System.out.println(somma(1.5, 2.5));
        System.out.println(somma(1, 2, 3));
    }
}

public class Varargs {
    static int somma(int... numeri) {
        int s = 0;
        for (int n : numeri) {
            s += n;
        }
        return s;
    }

    public static void main(String[] args) {
        System.out.println(somma());
        System.out.println(somma(5));
        System.out.println(somma(1, 2, 3, 4));
    }
}

